# -*- coding: utf-8 -*-
"""Lecture 29 vignette pool C -- Arrhythmias I: atrial flutter, atrial fibrillation (rate control,
cardioversion, anticoagulation), premature atrial contractions, and premature junctional
contractions with junctional rhythm (junctional questions carry the Lecture 30 objective).

KEYS ARE WRITTEN SHORT ON PURPOSE -- detail lives in the explanation.

Emphasis from the recording: "goal number one with A flutter and AFib is always ... rate control",
then anticoagulation, cardioversion only after 21 days of anticoagulation. Never keyed: the HAS-BLED
withholding threshold, "anticoagulation for all", score components (cms_e5l29_scope.py).
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from _cmse3_q import Q
from cms_e5l29_scope import *


def S(topic, io, q, opts, cite, slot):
    d = Q(topic, io, q, opts, cite); d["slot"] = slot; return d


def V(topic, io, q, opts, cite, slot, lead):
    d = S(topic, io, q, opts, cite, slot); d["lead"] = lead; return d


